# V28.8 PC-first full-universe scanner.
# Dot-source from pc-agent.ps1. Heavy breadth work stays on the Windows PC.
$script:PcFirstVersion='28.8'
$script:PcFirstUniverse=@()
$script:PcFirstRows=@{}
$script:PcFirstUniverseAt=[DateTime]::MinValue
$script:PcFirstShard=0
$script:PcFirstShardCount=4
$script:PcFirstLastFullSweepAt=$null
$script:PcFirstUniverseCache=Join-Path $CacheRoot 'pc-first-universe.json'
$script:PcFirstStateCache=Join-Path $CacheRoot 'pc-first-state.json'
function Limit-PcNumber([double]$v,[double]$lo,[double]$hi){return [Math]::Max($lo,[Math]::Min($hi,$v))}
function Save-PcFirstUniverse($Rows){try{[ordered]@{savedAt=[DateTime]::UtcNow.ToString('o');equities=$Rows}|ConvertTo-Json -Depth 5|Set-Content $script:PcFirstUniverseCache -Encoding UTF8}catch{}}
function Load-PcFirstUniverseCache(){if(-not(Test-Path $script:PcFirstUniverseCache)){return @()};try{$j=Get-Content $script:PcFirstUniverseCache -Raw|ConvertFrom-Json;return @($j.equities)}catch{return @()}}
function Update-PcFirstUniverse([switch]$Force){if(-not $Force -and $script:PcFirstUniverse.Count -gt 100 -and ([DateTime]::UtcNow-$script:PcFirstUniverseAt).TotalHours -lt 6){return $script:PcFirstUniverse};try{$u=Invoke-AgentPost '/api/agent/universe' ([ordered]@{scannerVersion=$script:PcFirstVersion;request='FULL_EQUITY_MASTER'});$rows=@($u.equities|Where-Object{$_.symbol});if($rows.Count -gt 100){$script:PcFirstUniverse=$rows;$script:PcFirstUniverseAt=[DateTime]::UtcNow;Save-PcFirstUniverse $rows;Write-AgentLog "PC-FIRST: Aktien-Master geladen: $($rows.Count) Werte.";return $rows}}catch{Write-AgentLog "PC-FIRST: Master-Abruf fehlgeschlagen: $($_.Exception.Message)"};$cached=Load-PcFirstUniverseCache;if($cached.Count){$script:PcFirstUniverse=$cached;$script:PcFirstUniverseAt=[DateTime]::UtcNow};return $script:PcFirstUniverse}
function Convert-PcFirstSpark($Json,[string]$Interval){$out=@();foreach($item in @($Json.spark.result)){try{$res=$item.response[0];if(-not $res){continue};$sym=([string]$item.symbol).ToUpper();$cl=@($res.indicators.quote[0].close|Where-Object{$_ -ne $null}|ForEach-Object{[double]$_});if(-not $sym -or $cl.Count-lt 2){continue};$price=[double]$res.meta.regularMarketPrice;if($price-le 0){$price=$cl[-1]};$prev=[double]$res.meta.previousClose;if($prev-le 0){$prev=$cl[0]};$day=if($prev-gt 0){100*($price/$prev-1)}else{0};$step20=if($Interval-eq '1m'){20}else{4};$step5=if($Interval-eq '1m'){5}else{1};$b20=$cl[[Math]::Max(0,$cl.Count-1-$step20)];$b5=$cl[[Math]::Max(0,$cl.Count-1-$step5)];$m20=if($b20-gt 0){100*($price/$b20-1)}else{0};$m5=if($b5-gt 0){100*($price/$b5-1)}else{0};$older=$cl[[Math]::Max(0,$cl.Count-1-2*$step5)];$prior5=if($older-gt 0 -and $b5-gt 0){100*($b5/$older-1)}else{0};$acc=$m5-$prior5;$marketTime=0;try{$marketTime=[int64]$res.meta.regularMarketTime}catch{};$ageMin=$null;if($marketTime-gt 0){$ageMin=[Math]::Max(0,([DateTimeOffset]::UtcNow.ToUnixTimeSeconds()-$marketTime)/60)};$out+=[pscustomobject]@{symbol=$sym;price=$price;dayPct=$day;momentum20Pct=$m20;momentum5Pct=$m5;acceleration5Pct=$acc;quoteAgeMinutes=$ageMin}}catch{}};return $out}
function Invoke-PcFirstSpark($Symbols,[string]$Interval='5m'){$symbols=@($Symbols|Where-Object{$_}|Select-Object -Unique);if(-not $symbols.Count){return @()};$url='https://query1.finance.yahoo.com/v7/finance/spark?symbols='+[uri]::EscapeDataString(($symbols -join ','))+'&range=1d&interval='+$Interval+'&indicators=close&includePrePost=false';$j=(Invoke-TrackedGet $url)|ConvertFrom-Json;return @(Convert-PcFirstSpark $j $Interval)}
function Get-PcFirstPreScore($q){$day=[double]$q.dayPct;$m20=[double]$q.momentum20Pct;$m5=[double]$q.momentum5Pct;$acc=[double]$q.acceleration5Pct;$s=50;$s+=Limit-PcNumber ($day*1.15) -12 11;$s+=Limit-PcNumber ($m20*5.5) -11 13;$s+=Limit-PcNumber ($m5*8) -8 10;$s+=Limit-PcNumber ($acc*2.5) -5 5;if($day-ge 12){$s-=12+[Math]::Min(10,($day-12)*.7)}elseif($day-ge 8){$s-=5};if($day-le -8){$s-=7};if($null -ne $q.quoteAgeMinutes -and [double]$q.quoteAgeMinutes-gt 20){$s-=10};return [Math]::Round((Limit-PcNumber $s 0 100),1)}
function Get-PcFirstDeepScore($q,[double]$PreScore){$s=$PreScore*.5+25;$s+=Limit-PcNumber ([double]$q.momentum20Pct*5) -10 12;$s+=Limit-PcNumber ([double]$q.momentum5Pct*7) -7 9;$s+=Limit-PcNumber ([double]$q.acceleration5Pct*2.2) -4 5;$day=[double]$q.dayPct;if($day-ge 12){$s-=14+[Math]::Min(12,($day-12)*.8)}elseif($day-ge 8){$s-=6};if($null -ne $q.quoteAgeMinutes -and [double]$q.quoteAgeMinutes-gt 20){$s-=12};return [Math]::Round((Limit-PcNumber $s 0 100),1)}
function Split-PcFirstChunks($Rows,[int]$Size){$all=@($Rows);for($i=0;$i-lt $all.Count;$i+=$Size){,$all[$i..([Math]::Min($all.Count-1,$i+$Size-1))]}}
function Invoke-PcFirstPipeline(){$universe=@(Update-PcFirstUniverse);if($universe.Count-lt 100){throw 'PC-FIRST: Kein Aktien-Master verfügbar.'};$shardIndex=$script:PcFirstShard;$script:PcFirstShard=($script:PcFirstShard+1)%$script:PcFirstShardCount;$symbols=@();for($i=0;$i-lt $universe.Count;$i++){if(($i%$script:PcFirstShardCount)-eq $shardIndex){$symbols+=[string]$universe[$i].symbol}};$requests=0;$errors=0;$now=[DateTime]::UtcNow;foreach($chunk in @(Split-PcFirstChunks $symbols 80)){try{$requests++;foreach($q in @(Invoke-PcFirstSpark $chunk '5m')){$pre=Get-PcFirstPreScore $q;$script:PcFirstRows[$q.symbol]=[ordered]@{symbol=$q.symbol;price=[double]$q.price;dayPct=[double]$q.dayPct;momentum20Pct=[double]$q.momentum20Pct;momentum5Pct=[double]$q.momentum5Pct;acceleration5Pct=[double]$q.acceleration5Pct;quoteAgeMinutes=$q.quoteAgeMinutes;preScore=$pre;updatedAt=$now.ToString('o')}}}catch{$errors++}};if($script:PcFirstShard-eq 0){$script:PcFirstLastFullSweepAt=$now};$freshCut=$now.AddMinutes(-12);$rows=@($script:PcFirstRows.Values|Where-Object{try{([DateTime]$_.updatedAt)-ge $freshCut}catch{$false}});$stage2=@($rows|Sort-Object @{Expression={[double]$_.preScore};Descending=$true}|Select-Object -First 400);$deepSymbols=@($stage2|Select-Object -First 120|ForEach-Object{$_.symbol});$deepMap=@{};foreach($chunk in @(Split-PcFirstChunks $deepSymbols 60)){try{$requests++;foreach($q in @(Invoke-PcFirstSpark $chunk '1m')){$pre=if($script:PcFirstRows.ContainsKey($q.symbol)){[double]$script:PcFirstRows[$q.symbol].preScore}else{Get-PcFirstPreScore $q};$deepMap[$q.symbol]=[ordered]@{symbol=$q.symbol;price=[double]$q.price;dayPct=[double]$q.dayPct;momentum20Pct=[double]$q.momentum20Pct;momentum5Pct=[double]$q.momentum5Pct;acceleration5Pct=[double]$q.acceleration5Pct;quoteAgeMinutes=$q.quoteAgeMinutes;preScore=$pre;deepScore=(Get-PcFirstDeepScore $q $pre)}}}catch{$errors++}};$final=@($stage2|ForEach-Object{$d=if($deepMap.ContainsKey($_.symbol)){$deepMap[$_.symbol]}else{[ordered]@{symbol=$_.symbol;price=$_.price;dayPct=$_.dayPct;momentum20Pct=$_.momentum20Pct;momentum5Pct=$_.momentum5Pct;acceleration5Pct=$_.acceleration5Pct;quoteAgeMinutes=$_.quoteAgeMinutes;preScore=$_.preScore;deepScore=$_.preScore}};[pscustomobject]$d}|Sort-Object @{Expression={[double]$_.deepScore};Descending=$true}|Select-Object -First 60);$leaders=@();$candidates=@();$rank=0;foreach($x in $final){$rank++;$stale=($null -ne $x.quoteAgeMinutes -and [double]$x.quoteAgeMinutes-gt 20);$confidence=Limit-PcNumber (.48+([double]$x.deepScore-50)/100) .35 .90;$leaders+=[ordered]@{symbol=$x.symbol;market='GLOBAL';source='PC-FIRST-V28.8';rank=$rank};$candidates+=[ordered]@{symbol=$x.symbol;rank=$rank;pcPreScore=[double]$x.preScore;pcDeepScore=[double]$x.deepScore;price=[double]$x.price;dayPct=[double]$x.dayPct;momentum20Pct=[double]$x.momentum20Pct;momentum5Pct=[double]$x.momentum5Pct;acceleration5Pct=[double]$x.acceleration5Pct;confidence=[Math]::Round($confidence,3);quoteAgeMinutes=$x.quoteAgeMinutes;stale=$stale}};$coverage=if($universe.Count){100*$rows.Count/$universe.Count}else{0};$summary=[ordered]@{version=28.8;updatedAt=$now.ToString('o');masterUniverseCount=$universe.Count;prescannedCount=$rows.Count;validQuoteCount=$rows.Count;stage2Count=$stage2.Count;deepCount=$deepMap.Count;finalistCount=$candidates.Count;shardIndex=$shardIndex;shardCount=$script:PcFirstShardCount;fullCycleCoveragePct=[Math]::Round([Math]::Min(100,$coverage),1);targetFullCycleMinutes=$script:PcFirstShardCount;lastFullSweepAt=if($script:PcFirstLastFullSweepAt){$script:PcFirstLastFullSweepAt.ToString('o')}else{$null};lastMinuteRefreshAt=$now.ToString('o');batchRequests=$requests;batchErrors=$errors;source='Windows-PC · Yahoo Spark Batch · Full-Master rolling';candidates=$candidates};return [ordered]@{summary=$summary;leaderEntries=$leaders}}
